 <div class="member-heading"><div><span class="yza-eyebrow">YZA MEMBER</span><h3>Pilih Promo YZA Member</h3></div><span class="promo-preview-status" aria-live="polite"></span></div>
 <div class="promo-selector-list">@forelse($promos as $promo)<label class="promo-option @if($selected===$promo->id_promo) is-selected @endif"><input type="radio" name="promo_id" value="{{ $promo->id_promo }}" @checked($selected===$promo->id_promo)><span><strong>{{ $promo->nama }}</strong><small>{{ $promo->jenis_benefit==='persentase' ? rtrim(rtrim(number_format((float)$promo->nilai_benefit,2,',','.'),'0'),'.').'%' : 'Rp '.number_format((float)$promo->nilai_benefit,0,',','.') }} · {{ ucfirst(str_replace('_',' ',$promo->berlaku_untuk)) }}</small><small>Min. Rp {{ number_format((float)$promo->minimum_transaksi,0,',','.') }} · berlaku {{ $promo->selesai_at?->format('d M Y') }}</small></span></label>@empty<p>Belum ada promo yang tersedia untuk transaksi ini.</p>@endforelse</div>
