</section>
<style>.promo-selector{margin:16px 0;padding:18px;border:1px solid rgba(229,29,42,.22);border-radius:14px;background:linear-gradient(135deg,rgba(229,29,42,.06),rgba(255,255,255,.9))}.promo-selector-list{display:grid;gap:10px}.promo-option{display:flex;gap:12px;padding:13px;border:1px solid #e1e4e8;border-radius:10px;background:#fff;cursor:pointer}.promo-option:has(input:checked){border-color:#e51d2a;box-shadow:0 0 0 2px rgba(229,29,42,.14)}.promo-option input{accent-color:#e51d2a}.promo-option span{display:grid;gap:4px}.promo-option small{color:#6c7480}.promo-summary{display:grid;gap:7px;margin-top:14px;padding-top:14px;border-top:1px dashed #ccd2d8}.promo-summary span,.promo-summary strong{display:flex;justify-content:space-between}.promo-summary strong{font-size:1.1rem;color:#e51d2a}</style>
<script>document.querySelectorAll('[data-promo-selector]').forEach(function(box){const form=box.closest('form')||document.querySelector('form');const source=box.dataset.subtotalSource?document.querySelector(box.dataset.subtotalSource):null;function updateSubtotal(){if(source){box.dataset.subtotal=source.value||source.dataset.price||0;}}function sync(id){if(form){let h=form.querySelector('[data-promo-hidden]');if(!h){h=document.createElement('input');h.type='hidden';h.name='promo_id';h.dataset.promoHidden='1';form.appendChild(h)}h.value=id||'';}}updateSubtotal();if(source){source.addEventListener('change',updateSubtotal);source.addEventListener('input',updateSubtotal)}box.querySelectorAll('input[name="promo_id"]').forEach(function(input){input.addEventListener('change',async function(){updateSubtotal();sync(this.value);box.querySelector('.promo-preview-status').textContent='Menghitung promo...';const q=new URLSearchParams({promo_id:this.value,scope:box.dataset.scope,subtotal:box.dataset.subtotal});const res=await fetch('{{ route('pelanggan.promo.preview') }}?'+q,{headers:{Accept:'application/json'}});const data=await res.json();if(!res.ok){box.querySelector('.promo-preview-status').textContent='Promo sudah tidak tersedia. Silakan pilih promo lain.';sync('');return}box.querySelector('[data-promo-subtotal]').textContent='Rp '+Number(data.subtotal).toLocaleString('id-ID');box.querySelector('[data-promo-discount]').textContent='-Rp '+Number(data.discount).toLocaleString('id-ID');box.querySelector('[data-promo-total]').textContent='Rp '+Number(data.total_final).toLocaleString('id-ID');box.querySelector('.promo-summary').hidden=false;box.querySelector('.promo-preview-status').textContent='✓ Promo berhasil diterapkan';});});const remove=box.querySelector('[data-promo-remove]');if(remove)remove.addEventListener('click',function(){box.querySelectorAll('input[name="promo_id"]').forEach(i=>i.checked=false);sync('');box.querySelector('.promo-summary').hidden=true;box.querySelector('.promo-preview-status').textContent='Promo dihapus';});});</script>
